#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "syrk.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize A and C as in the original C version.
 *
 * C: n x n  (C[i][j])
 * A: n x m  (A[i][j])
 *
 * Halide Buffers are laid out as:
 *   C(j, i) corresponds to C[i][j]
 *   A(j, i) corresponds to A[i][j]
 */
static
void init_array(int n, int m,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_C("init_C");

    // A[i][j] = ( (i*j + 1) % n ) / n;
    // A is n x m, mapped as A(j, i)
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // C[i][j] = ( (i*j + 2) % m ) / m;
    // C is n x n, mapped as C(j, i)
    init_C(j, i) = cast<num_t>((i * j + 2) % m) / cast<int>(m);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;
    int m = M;

    // input data
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: n x n   (C(j, i) == C[i][j])
    //   A: m x n   (A(k, i) == A[i][k])
    Buffer<num_t, 2> C(n, n);
    Buffer<num_t, 2> A(m, n);

    // ImageParams for Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // initialize data
    init_array(n, m, &alpha, &beta, C, A);

    // Declare Vars and RDom
    Var i("i"), j("j");
    // k runs over the "M" dimension (the first dimension of A)
    RDom k(0, A.dim(0).extent(), "k");

    // Define the SYRK kernel:
    //
    // Original C:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < m; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We compute:
    //   - for j <= i: C(i,j) = beta * C(i,j) + alpha * sum_k A(i,k)*A(j,k)
    //   - for j >  i: C(i,j) = original C(i,j)  (unchanged)
    //
    // In Halide coordinates: C(j, i) == C[i][j]
    //                         A(k, i) == A[i][k]
    //                         A(k, j) == A[j][k]
    Func syrk("syrk");

    // Pure definition: apply beta on lower triangle, keep upper as-is
    syrk(j, i) = select(j <= i,
                        Expr(beta) * C_param(j, i),
                        C_param(j, i));

    // Reduction over k: add alpha * A[i][k] * A[j][k] to lower triangle
    syrk(j, i) += select(j <= i,
                         Expr(alpha) * A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // Schedule: keep traversal order close to the original
    syrk.reorder(j, i);                 // j is the fast (x) dimension
    syrk.update().reorder(j, k, i);     // inner loops: j, then k, then i

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);

    // JIT compile
    syrk.compile_jit();

    // Time the kernel execution
    auto start = std::chrono::high_resolution_clock::now();

    // run kernel
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // print results (similar to original print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}

#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, M, etc.)
#include "syrk.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize arrays A and C as in the original C version.
static
void init_array(int n, int m,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    // Original:
    // A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
    // A is n x m in C => Buffer A is (m, n): A(j, i) == A[i][j]
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // Original:
    // C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
    // C is n x n in C => Buffer C is (n, n): C(j, i) == C[i][j]
    init_C(j, i) = cast<num_t>((i * j + 2) % m) / cast<int>(m);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;
    int m = M;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is n x n in C, indexed C[i][j] => Buffer(width=n, height=n), C(j, i).
    // A is n x m in C, indexed A[i][j] => Buffer(width=m, height=n), A(j, i).
    Buffer<num_t, 2> C(n, n);
    Buffer<num_t, 2> A(m, n);

    // ImageParams that will wrap the above Buffers for the Halide pipeline.
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data.
    init_array(n, m, &alpha, &beta, C, A);

    // Bind Buffers to ImageParams.
    C_param.set(C);
    A_param.set(A);

    // Halide Vars and RDom.
    Var i("i"), j("j");
    // Extent in the k-dimension equals the width of A (m).
    RDom k(0, A.dim(0).extent(), "k");

    // SYRK kernel:
    //
    // BLAS:
    //   C := alpha * A * A^T + beta * C
    // lower triangle (j <= i) is updated; upper triangle is left unchanged.
    //
    // Original C:
    //
    // for (i = 0; i < N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express the same computation as:
    //
    // if (j <= i)
    //   C_new(i, j) = beta * C(i, j) + alpha * sum_k A(i, k) * A(j, k);
    // else
    //   C_new(i, j) = C(i, j);
    //
    // With our Buffer layout, C(i,j) in C becomes C_param(j, i),
    // A(i,k) becomes A_param(k, i), A(j,k) becomes A_param(k, j).

    Func syrk("syrk");

    // Pure definition: scale lower triangle by beta, upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        Expr(beta) * C_param(j, i),
                        C_param(j, i));

    // Reduction: accumulate alpha * A(i,k) * A(j,k) into lower triangle.
    syrk(j, i) += select(j <= i,
                         Expr(alpha) * A_param(k, i) * A_param(k, j),
                         0);

    // Schedule:
    // Make the pure step iterate with i as outer loop and j as inner loop
    // (this matches the original i,j nesting; default ordering already does this
    // for arguments (j, i), but we spell it out explicitly).
    syrk.reorder(j, i);

    // For the update step, we want loops of the form:
    //   for i:
    //     for k:
    //       for j:
    // which is achieved by:
    syrk.update().reorder(j, k, i);

    // Compile the kernel to machine code.
    syrk.compile_jit();

    // Measure execution time.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel.
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (mainly to prevent dead-code elimination
    // in some testing setups). We follow the pattern from the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(jj, ii) corresponds to C[ii][jj] in the original C code.
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}

