#include <iostream>

#include "Halide.h"

// include common definitions (e.g., DATA_TYPE, N, M)
#include "defines.hpp"

// include benchmark-specific definitions
#include "syrk.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and C, and scalars alpha and beta,
 * matching the semantics of the original C version.
 *
 * Original C:
 *
 *   *alpha = 1.5;
 *   *beta  = 1.2;
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < m; j++)
 *       A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
 *
 * Mapping to Halide Buffers:
 *   C is Buffer<num_t>(n, n) with indexing C(j, i) == C[i][j]
 *   A is Buffer<num_t>(m, n) with indexing A(k, i) == A[i][k]
 */
static void init_array(int n, int m,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_A("init_A"), init_C("init_C");

    // A has shape (m, n): dim 0 = j (0..m-1), dim 1 = i (0..n-1)
    // A[i][j] -> A(j, i)
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // C has shape (n, n): dim 0 = j, dim 1 = i
    // C[i][j] -> C(j, i)
    init_C(j, i) = cast<num_t>((i * j + 2) % m) / cast<int>(m);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: N x N  (C(i,j) in C is C(j,i) in Buffer)
    //   A: N x M  (A(i,k) in C is A(k,i) in Buffer)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams for the kernel
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data
    init_array(n, m, &alpha, &beta, C, A);

    Var i("i"), j("j");
    // A.dim(0) is the k-dimension (0..m-1)
    RDom k(0, A.dim(0).extent(), "k");

    Func syrk("syrk");

    // Map:
    //   C[i][j] in C code  -> C_param(j, i)
    //   A[i][k]            -> A_param(k, i)
    //   A[j][k]            -> A_param(k, j)
    //
    // Original kernel:
    //   for (i = 0; i < N; i++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] *= beta;
    //     for (k = 0; k < M; k++)
    //       for (j = 0; j <= i; j++)
    //         C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    //
    // Mathematically:
    //   For j <= i:
    //     C[i][j] = beta * C[i][j] +
    //               alpha * sum_k A[i][k] * A[j][k]
    //   For j > i:
    //     C[i][j] unchanged
    //
    // We express this as a reduction over k, with a select(j <= i)
    // to keep the strict lower-triangular semantics.

    Expr alpha_e = Expr(alpha);
    Expr beta_e  = Expr(beta);

    // Initial scaling by beta only for j <= i; otherwise keep C unchanged.
    syrk(j, i) = select(j <= i,
                        beta_e * C_param(j, i),
                        C_param(j, i));

    // Accumulate alpha*A[i][k]*A[j][k] only for j <= i; add 0 otherwise.
    syrk(j, i) += select(j <= i,
                         alpha_e * A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // Schedule:
    // Default pure loop order for syrk(j,i) is:
    //   for i:
    //     for j:
    //       syrk(j,i) = ...
    //
    // The update with RDom k by default becomes:
    //   for i:
    //     for j:
    //       for k:
    //         syrk(j,i) += ...
    //
    // We reorder the update to more closely resemble the original:
    //   for i:
    //     for k:
    //       for j:
    //         ...
    syrk.update().reorder(j, k, i);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);

    // Compile the kernel
    syrk.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write results back into C
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results, similar to the gemm example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C(ii,jj) in C code is C(jj,ii) in the Buffer
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
