#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common PolyBench-style definitions (e.g. DATA_TYPE, N, M)
#include "defines.hpp"

// include benchmark-specific definitions (e.g. N, M for syrk)
#include "syrk.hpp"

using num_t = DATA_TYPE;
using namespace Halide;

/**
 * Initialize arrays A and C and scalars alpha, beta.
 *
 * C and A are Halide Buffers with the following layout:
 *   - Original C is declared in C as C[i][j] with shape (n x n).
 *     We map it to Buffer C(j, i) with shape (n (cols), n (rows)).
 *   - Original A is declared in C as A[i][j] with shape (n x m).
 *     We map it to Buffer A(j, i) with shape (m (cols), n (rows)).
 *
 * This matches the mapping rule:
 *   C-array DATA_TYPE A[NI][NJ]  -> Halide::Buffer<DATA_TYPE>(NJ, NI)
 */
static void init_array(int n, int m,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");
    Func init_A("init_A"), init_C("init_C");

    // A[i][j] = ((i * j + 1) % n) / n;
    // A is N x M, mapped as A(j, i)
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // C[i][j] = ((i * j + 2) % m) / m;
    // C is N x N, mapped as C(j, i)
    init_C(j, i) = cast<num_t>((i * j + 2) % m) / cast<int>(m);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size (from PolyBench-style headers)
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: N x N -> Buffer(n (cols j), n (rows i))
    //   A: N x M -> Buffer(m (cols j), n (rows i))
    Buffer<num_t, 2> C(n, n);
    Buffer<num_t, 2> A(m, n);

    // ImageParams for Halide pipeline inputs
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data
    init_array(n, m, &alpha, &beta, C, A);

    // Bind Buffers to ImageParams
    C_param.set(C);
    A_param.set(A);

    // Vars and reduction domain
    Var j("j"), i("i");     // j: column, i: row (C(j, i) == C[i][j] in C code)
    RDom k(0, A.dim(0).extent(), "k"); // k iterates over M (columns of A)

    // Define syrk Func:
    //
    // Original kernel (BLAS SYRK, lower triangle):
    //
    // for (i = 0; i < N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We map C[i][j] -> C(j, i), A[i][k] -> A(k, i), A[j][k] -> A(k, j).
    // We compute the full N x N box, but only update the lower triangle (j <= i).
    Func syrk("syrk");

    // Pure definition: apply beta scaling only to the lower triangle; leave upper as-is.
    syrk(j, i) = select(j <= i,
                        Expr(beta) * C_param(j, i),
                        C_param(j, i));

    // Update definition: accumulate alpha * A[i][k] * A[j][k] into the lower triangle.
    // Upper triangle gets +0, so it remains unchanged.
    syrk(j, i) += select(j <= i,
                         Expr(alpha) * A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // The default schedule iterates i (y) outer, j (x) inner, then k,
    // which matches the original i/j/k nesting order up to independent reordering.

    // JIT-compile the kernel
    syrk.compile_jit();

    // Time the kernel execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the output, similar to PolyBench's print_array
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // Remember: C(j, i) corresponds to original C[i][j]
                std::cerr << C(j, i) << '\n';
            }
        }
    }

    // Print timing in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
